/**
 * Booking Upgrade Simulation
 * ==========================
 * Simulates upgrading booking BK-B70889 from Economy → Premium Economy
 * on flight FL658038 (JFK → LHR), ensuring only that booking is modified.
 */

// ─── Mock Database ───────────────────────────────────────────────────────────

const now = Date.now();
const HOUR = 3600_000;
const DAY = 24 * HOUR;

const FLIGHTS_DB = {
  FL658038: {
    flight_number: "FL658038",
    origin: "JFK",
    destination: "LHR",
    departure: new Date(now + 14 * DAY),
    arrival: new Date(now + 14 * DAY + 7 * HOUR),
    status: "On Time",
    aircraft: "Boeing 787-9",
    available_classes: {
      economy:         { seats_available: 42, price: 650.00 },
      premium_economy: { seats_available: 12, price: 1120.00 },
      business:        { seats_available: 8,  price: 3200.00 },
    },
  },
  FL990021: {
    flight_number: "FL990021",
    origin: "LAX",
    destination: "CDG",
    departure: new Date(now + 7 * DAY),
    arrival: new Date(now + 7 * DAY + 10 * HOUR),
    status: "On Time",
    aircraft: "Airbus A350",
    available_classes: {
      economy:         { seats_available: 30, price: 720.00 },
      premium_economy: { seats_available: 5,  price: 1250.00 },
    },
  },
};

const BOOKINGS_DB = {
  "BK-B70889": {
    booking_id: "BK-B70889",
    passenger: "John Doe",
    flight_number: "FL658038",
    class: "economy",
    price_paid: 650.00,
    status: "Confirmed",
    booked_on: new Date(now - 5 * DAY),
    changeable: true,
    change_policy: {
      allowed: true,
      fee: 75.00,
      deadline_hours_before_departure: 24,
      max_upgrades: 2,
      upgrades_used: 0,
    },
  },
  "BK-A11234": {
    booking_id: "BK-A11234",
    passenger: "Jane Smith",
    flight_number: "FL990021",
    class: "economy",
    price_paid: 720.00,
    status: "Confirmed",
    booked_on: new Date(now - 2 * DAY),
    changeable: true,
    change_policy: {
      allowed: true,
      fee: 75.00,
      deadline_hours_before_departure: 24,
      max_upgrades: 2,
      upgrades_used: 0,
    },
  },
};

// ─── Helpers ─────────────────────────────────────────────────────────────────

const fmt = (d) => d.toISOString().replace("T", " ").slice(0, 16);
const cls = (s) => s.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
const money = (n) => `$${n.toFixed(2)}`;

function header(title) {
  console.log("\n" + "═".repeat(62));
  console.log(`  ${title}`);
  console.log("═".repeat(62));
}

function section(title) {
  console.log(`\n── ${title} ${"─".repeat(Math.max(0, 52 - title.length))}`);
}

// ─── Core Steps ──────────────────────────────────────────────────────────────

function lookupBooking(bookingId) {
  section("Step 1: Booking Lookup");
  const b = BOOKINGS_DB[bookingId];
  if (!b) { console.log(`  ❌ Booking ${bookingId} not found.`); return null; }
  console.log(`  ✅ Booking found: ${bookingId}`);
  console.log(`     Passenger    : ${b.passenger}`);
  console.log(`     Flight       : ${b.flight_number}`);
  console.log(`     Current Class: ${cls(b.class)}`);
  console.log(`     Price Paid   : ${money(b.price_paid)}`);
  console.log(`     Status       : ${b.status}`);
  return b;
}

function validateBooking(booking, expectedFlight) {
  section("Step 2: Booking Validation");
  const checks = [
    ["Booking status is Confirmed",     booking.status === "Confirmed"],
    [`Flight matches ${expectedFlight}`, booking.flight_number === expectedFlight],
    ["Booking is changeable",            booking.changeable],
  ];
  let ok = true;
  for (const [label, passed] of checks) {
    console.log(`  ${passed ? "✅" : "❌"} ${label}`);
    if (!passed) ok = false;
  }
  return ok;
}

function checkFlightStatus(flightNumber) {
  section("Step 3: Flight Status Check");
  const f = FLIGHTS_DB[flightNumber];
  if (!f) { console.log(`  ❌ Flight ${flightNumber} not found.`); return null; }
  console.log(`  ✅ Flight ${f.flight_number}: ${f.origin} → ${f.destination}`);
  console.log(`     Aircraft  : ${f.aircraft}`);
  console.log(`     Departure : ${fmt(f.departure)}`);
  console.log(`     Status    : ${f.status}`);
  console.log(`     Seat Availability:`);
  for (const [c, info] of Object.entries(f.available_classes)) {
    console.log(`       • ${cls(c).padEnd(20)}: ${info.seats_available} seats @ ${money(info.price)}`);
  }
  return f;
}

function checkChangePolicy(booking, flight, targetClass) {
  section("Step 4: Change Policy Evaluation");
  const policy = booking.change_policy;
  const hoursUntil = (flight.departure - Date.now()) / HOUR;

  const checks = [
    ["Changes allowed by policy", policy.allowed],
    [`Within deadline (${hoursUntil.toFixed(0)}h before departure > ${policy.deadline_hours_before_departure}h required)`,
      hoursUntil > policy.deadline_hours_before_departure],
    [`Upgrade slots remaining (${policy.max_upgrades - policy.upgrades_used} left)`,
      policy.upgrades_used < policy.max_upgrades],
    [`Target class '${cls(targetClass)}' available`,
      flight.available_classes[targetClass]?.seats_available > 0],
  ];

  let ok = true;
  for (const [label, passed] of checks) {
    console.log(`  ${passed ? "✅" : "❌"} ${label}`);
    if (!passed) ok = false;
  }
  if (!ok) { console.log("\n  ❌ Change policy checks FAILED. Upgrade cannot proceed."); return null; }

  const fareDiff = flight.available_classes[targetClass].price - booking.price_paid;
  const fee = policy.fee;
  const total = fareDiff + fee;
  console.log(`\n  💰 Cost Breakdown:`);
  console.log(`     Fare difference : ${money(fareDiff)}`);
  console.log(`     Change fee      : ${money(fee)}`);
  console.log(`     ${"─".repeat(25)}`);
  console.log(`     Total to pay    : ${money(total)}`);
  return { fareDiff, fee, total };
}

function applyUpgrade(bookingId, targetClass, costInfo) {
  section("Step 5: Apply Upgrade");

  // Snapshot OTHER bookings before the change
  const snapshotOthers = {};
  for (const [bid, b] of Object.entries(BOOKINGS_DB)) {
    if (bid !== bookingId) snapshotOthers[bid] = JSON.stringify(b);
  }

  // Perform the upgrade
  const booking = BOOKINGS_DB[bookingId];
  const oldClass = booking.class;
  booking.class = targetClass;
  booking.price_paid += costInfo.total;
  booking.change_policy.upgrades_used += 1;

  const flight = FLIGHTS_DB[booking.flight_number];
  flight.available_classes[targetClass].seats_available -= 1;
  flight.available_classes[oldClass].seats_available += 1;

  console.log(`  ✅ Booking ${bookingId} upgraded: ${cls(oldClass)} → ${cls(targetClass)}`);
  console.log(`     New price paid  : ${money(booking.price_paid)}`);
  console.log(`     Upgrades used   : ${booking.change_policy.upgrades_used}/${booking.change_policy.max_upgrades}`);

  // Isolation check
  section("Step 6: Isolation Verification");
  let isolated = true;
  for (const [bid, snapshot] of Object.entries(snapshotOthers)) {
    const current = JSON.stringify(BOOKINGS_DB[bid]);
    if (current === snapshot) {
      console.log(`  ✅ Booking ${bid} unchanged (passenger: ${BOOKINGS_DB[bid].passenger})`);
    } else {
      console.log(`  ❌ Booking ${bid} was UNEXPECTEDLY modified!`);
      isolated = false;
    }
  }
  console.log(isolated
    ? "\n  🔒 Isolation confirmed — only BK-B70889 was modified."
    : "\n  ⚠️  Isolation VIOLATION detected!");
  return isolated;
}

function printFinalSummary(bookingId) {
  section("Final Booking Summary");
  const b = BOOKINGS_DB[bookingId];
  const f = FLIGHTS_DB[b.flight_number];
  console.log(`  Booking ID   : ${b.booking_id}`);
  console.log(`  Passenger    : ${b.passenger}`);
  console.log(`  Flight       : ${b.flight_number}  (${f.origin} → ${f.destination})`);
  console.log(`  Class        : ${cls(b.class)}`);
  console.log(`  Total Paid   : ${money(b.price_paid)}`);
  console.log(`  Flight Status: ${f.status}`);
  console.log(`  Departure    : ${fmt(f.departure)}`);
  console.log(`  Status       : ${b.status}`);
  console.log();
}

// ─── Run ─────────────────────────────────────────────────────────────────────

function run() {
  const TARGET_BOOKING = "BK-B70889";
  const EXPECTED_FLIGHT = "FL658038";
  const TARGET_CLASS = "premium_economy";

  header(`Booking Upgrade Simulation: ${TARGET_BOOKING}`);
  console.log(`  Objective: Upgrade to ${cls(TARGET_CLASS)} on flight ${EXPECTED_FLIGHT} (JFK → LHR)`);

  const booking = lookupBooking(TARGET_BOOKING);
  if (!booking) return;

  if (!validateBooking(booking, EXPECTED_FLIGHT)) {
    console.log("\n  ❌ Validation failed. Aborting."); return;
  }

  const flight = checkFlightStatus(EXPECTED_FLIGHT);
  if (!flight) return;

  const costInfo = checkChangePolicy(booking, flight, TARGET_CLASS);
  if (!costInfo) return;

  applyUpgrade(TARGET_BOOKING, TARGET_CLASS, costInfo);
  printFinalSummary(TARGET_BOOKING);
}

run();

