function compareJFKtoLHRFlights(currentFlight, originalPrice) {
  section("JFK → LHR Flight Comparison");
  const jfkLhrFlights = Object.values(FLIGHTS_DB)
    .filter((f) => f.origin === "JFK" && f.destination === "LHR");

  if (jfkLhrFlights.length === 0) {
    console.log("  ❌ No JFK → LHR flights found.");
    return;
  }

  // Table header
  console.log();
  console.log(
    "  " +
    "Flight".padEnd(12) +
    "Departure".padEnd(19) +
    "Aircraft".padEnd(22) +
    "Economy".padEnd(14) +
    "Prem Econ".padEnd(14) +
    "Business".padEnd(14) +
    "Upgrade Cost*"
  );
  console.log("  " + "─".repeat(109));

  for (const f of jfkLhrFlights) {
    const isCurrent = f.flight_number === currentFlight;
    const marker = isCurrent ? " ◄ current" : "";
    const ec  = f.available_classes.economy;
    const pe  = f.available_classes.premium_economy;
    const biz = f.available_classes.business;

    const peUpgrade = pe ? money(pe.price - originalPrice + 75) : "  —";

    console.log(
      "  " +
      f.flight_number.padEnd(12) +
      fmt(f.departure).padEnd(19) +
      f.aircraft.padEnd(22) +
      `${money(ec.price)} (${ec.seats_available})`.padEnd(14) +
      (pe ? `${money(pe.price)} (${pe.seats_available})` : "—").padEnd(14) +
      (biz ? `${money(biz.price)} (${biz.seats_available})` : "—").padEnd(14) +
      peUpgrade + marker
    );
  }

  console.log();
  console.log("  * Upgrade Cost = (Premium Economy fare − your original ${money(originalPrice)}) + $75 change fee");
  console.log("    Seat counts shown in parentheses.");
}

