  console.log(`  │ Price Paid   : ${money(b.price_paid)}`);
  console.log(`  │ Status       : ${b.status}`);
  console.log(`  │ Flight Status: ${f.status}`);
  console.log(`  │ Upgrades Used: ${b.change_policy.upgrades_used}/${b.change_policy.max_upgrades}`);
  console.log(`  └──────────────────────────────────────────────`);
}

// ─── Execute ─────────────────────────────────────────────────────────────────

function run() {
  const TARGET = "BK-B70889";
  const RETURN = "BK-CE5BA9";
  const TARGET_CLASS = "premium_economy";

  header("Upgrade Execution: BK-B70889 → Premium Economy");

  // ── Pre-upgrade snapshot ───────────────────────────────────────────────────
  section("Pre-Upgrade State");
  const snapshotAll = {};
  for (const [bid, b] of Object.entries(BOOKINGS_DB)) {
    snapshotAll[bid] = JSON.parse(JSON.stringify(b));
  }
  const snapshotSeats = JSON.parse(JSON.stringify(
    FLIGHTS_DB["FL658038"].available_classes
  ));

  console.log();
  printBookingCard(BOOKINGS_DB[TARGET], "OUTBOUND — BK-B70889 (to be upgraded)");
  console.log();
  printBookingCard(BOOKINGS_DB[RETURN], "RETURN   — BK-CE5BA9 (must NOT change)");

  // ── Compute costs ──────────────────────────────────────────────────────────
  section("Upgrade Transaction");
  const booking = BOOKINGS_DB[TARGET];
  const flight  = FLIGHTS_DB[booking.flight_number];
  const oldClass = booking.class;
  const fareDiff = flight.available_classes[TARGET_CLASS].price - booking.price_paid;
  const fee = booking.change_policy.fee;
  const total = fareDiff + fee;

  console.log(`  Action       : ${cls(oldClass)} → ${cls(TARGET_CLASS)}`);
  console.log(`  Fare diff    : ${money(fareDiff)}`);
  console.log(`  Change fee   : ${money(fee)}`);
  console.log(`  Total charge : ${money(total)}`);
  console.log();

  // ── Apply the change ───────────────────────────────────────────────────────
  console.log("  Applying upgrade...");
  booking.class = TARGET_CLASS;
  booking.price_paid += total;
  booking.change_policy.upgrades_used += 1;
  flight.available_classes[TARGET_CLASS].seats_available -= 1;
  flight.available_classes[oldClass].seats_available += 1;

  const timestamp = new Date().toISOString().replace("T", " ").slice(0, 19);
  console.log(`  ✅ Upgrade applied successfully at ${timestamp}`);
  console.log(`  Transaction ID: TXN-${Date.now().toString(36).toUpperCase()}`);

  // ── Post-upgrade state ─────────────────────────────────────────────────────
  section("Post-Upgrade State");
  console.log();
  printBookingCard(BOOKINGS_DB[TARGET], "OUTBOUND — BK-B70889 (UPGRADED)");
  console.log();
  printBookingCard(BOOKINGS_DB[RETURN], "RETURN   — BK-CE5BA9 (should be unchanged)");

  // ── Detailed diff ──────────────────────────────────────────────────────────
  section("Change Audit — BK-B70889");
  const before = snapshotAll[TARGET];
  const after  = BOOKINGS_DB[TARGET];
  const changes = [
    { field: "Class",         old: cls(before.class),                        now: cls(after.class) },
    { field: "Price Paid",    old: money(before.price_paid),                 now: money(after.price_paid) },
    { field: "Upgrades Used", old: `${before.change_policy.upgrades_used}`,  now: `${after.change_policy.upgrades_used}` },
  ];
  const unchanged = [
    { field: "Booking ID",    value: after.booking_id },
    { field: "Passenger",     value: after.passenger },
    { field: "Flight",        value: after.flight_number },
    { field: "Status",        value: after.status },
  ];

  console.log("  Changed fields:");
  for (const c of changes) {
    console.log(`    📝 ${c.field.padEnd(15)}: ${c.old}  →  ${c.now}`);
  }
  console.log("  Unchanged fields:");
  for (const u of unchanged) {
    console.log(`    ✅ ${u.field.padEnd(15)}: ${u.value}`);
  }

  // ── Seat inventory change ──────────────────────────────────────────────────
  section("Seat Inventory Update — FL658038");
  const seatsAfter = FLIGHTS_DB["FL658038"].available_classes;
  for (const c of ["economy", "premium_economy", "business"]) {
    const bef = snapshotSeats[c].seats_available;
    const aft = seatsAfter[c].seats_available;
    const diff = aft - bef;
    const tag = diff !== 0 ? ` (${diff > 0 ? "+" : ""}${diff})` : "";
    const icon = diff !== 0 ? "📝" : "✅";
    console.log(`  ${icon} ${cls(c).padEnd(20)}: ${bef} → ${aft}${tag}`);
  }

  // ── Full isolation verification ────────────────────────────────────────────
  section("Isolation Verification");
  let allSafe = true;

  for (const [bid, beforeBooking] of Object.entries(snapshotAll)) {
    if (bid === TARGET) continue;
    const current = BOOKINGS_DB[bid];
    const beforeStr = JSON.stringify(beforeBooking);
    const afterStr  = JSON.stringify(current);
    const match = beforeStr === afterStr;

    if (match) {
      console.log(`  ✅ ${bid} (${current.passenger}) — ${FLIGHTS_DB[current.flight_number].origin} → ${FLIGHTS_DB[current.flight_number].destination}`);
      console.log(`     Class: ${cls(current.class)} | Paid: ${money(current.price_paid)} | Status: ${current.status}`);
      console.log(`     → All fields identical to pre-upgrade snapshot`);
    } else {
      console.log(`  ❌ ${bid} — UNEXPECTED MODIFICATION DETECTED`);
      allSafe = false;
    }
  }

  // ── Final verdict ──────────────────────────────────────────────────────────
  section("Final Verdict");
  if (allSafe) {
    console.log("  ╔══════════════════════════════════════════════════════╗");
    console.log("  ║  ✅  UPGRADE SUCCESSFUL                             ║");
    console.log("  ║                                                      ║");
    console.log(`  ║  BK-B70889: Economy → Premium Economy                ║`);
    console.log(`  ║  Flight   : FL658038  (JFK → LHR)                    ║`);
    console.log(`  ║  Charged  : ${money(total).padEnd(42)}║`);
    console.log(`  ║  New Total: ${money(after.price_paid).padEnd(42)}║`);
    console.log("  ║                                                      ║");
    console.log("  ║  🔒 BK-CE5BA9 (return LHR→JFK): UNTOUCHED           ║");
    console.log("  ║  🔒 All other bookings: UNTOUCHED                    ║");
    console.log("  ╚══════════════════════════════════════════════════════╝");
  } else {
    console.log("  ⚠️  ISOLATION FAILURE — review logs above.");
  }
  console.log();
}

run();
